from pathlib import Path
import json,datetime
root=Path('guide');p=root/'_waves/C10.screens.json';d=json.loads(p.read_text());ss=d['screens']
def c(name,role='button'):return {'click':{'role':role,'name':name,'exact':True}}
def w(text):return {'waitFor':{'text':text},'timeout':300000}
def f(label,value):return {'fill':{'label':label,'exact':True},'value':value}
def add(n,shows,a,e,after=None):
 if any(s['name']==n for s in ss):return
 s=dict(name=n,shows=shows,actions=a,expect=e,height=1500)
 if after:s['after']=after
 ss.append(s)
def job(key):return [{'goto':'/settings/jobs'},{'click':{'css':f'tr:has(td[data-label="Workspace"]:text-is("{key}")) a.job-name'}}]
def person(name):return [{'goto':'/settings/people'},f('Search people',name),{'click':{'css':f'nav[aria-label="People"] button:has-text("{name}")'}}]
def hook(name):return [{'goto':'/settings/webhooks'},{'click':{'css':f'nav button:has-text("{name}")'}}]
